ALTER POLICY "Forum media upload own" ON storage.objects WITH CHECK (bucket_id = 'forum-media' AND (storage.foldername(name))[1] = auth.uid()::text);
ALTER TABLE public.forum_replies DROP CONSTRAINT forum_replies_content_check;
ALTER TABLE public.forum_replies ADD CONSTRAINT forum_replies_content_check CHECK (length(content) <= 5000 AND (length(trim(content)) >= 1 OR attachment_path IS NOT NULL));
CREATE OR REPLACE FUNCTION public.validate_forum_media() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE m jsonb; expected text; BEGIN IF NEW.attachment_path IS NOT NULL THEN SELECT metadata INTO m FROM storage.objects WHERE bucket_id = 'forum-media' AND name = NEW.attachment_path; expected := split_part(lower(coalesce(m->>'mimetype','')), '/', 1); IF split_part(NEW.attachment_path, '/', 1) <> NEW.user_id::text OR m IS NULL OR expected <> NEW.attachment_type OR lower(m->>'mimetype') NOT IN ('image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime','audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/wav') OR coalesce((m->>'size')::bigint,0) NOT BETWEEN 1 AND 52428800 THEN RAISE EXCEPTION 'Pièce jointe invalide'; END IF; END IF; RETURN NEW; END $$;